export interface GradePeriod {
  activities: (number | null)[];
  exam: number | null;
}

export interface Student {
  id: string;
  name: string;
  bimesters: {
    1: GradePeriod;
    2: GradePeriod;
    3: GradePeriod;
    4: GradePeriod;
  };
  rec1: number | null; // Substitui menor nota de B1 ou B2
  rec2: number | null; // Substitui menor nota de B3 ou B4
  finalExam: number | null;
}

export interface ClassRoom {
  id: string;
  name: string;
  subject: string;
  year: string;
  activityCount: number; // Quantas colunas de atividade por bimestre
  students: Student[];
}

export type View = 'list' | 'detail' | 'create';
export type BimesterTab = 1 | 2 | 3 | 4 | 'annual';

import { GoogleGenAI } from "@google/genai";
import { ClassRoom } from "../types";

export const analyzeClassPerformance = async (classData: ClassRoom): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Simplifica dados para a IA focar no que importa (médias e riscos)
  const analysisData = classData.students.map(s => {
    const calcB = (b: any) => {
      const avgAct = b.activities.filter((v:any) => v !== null).reduce((a:any, b:any) => a + b, 0) / (b.activities.filter((v:any) => v !== null).length || 1);
      return ((avgAct + (b.exam || 0)) / 2).toFixed(1);
    };

    return {
      nome: s.name,
      bimesters: [calcB(s.bimesters[1]), calcB(s.bimesters[2]), calcB(s.bimesters[3]), calcB(s.bimesters[4])],
      rec1: s.rec1,
      rec2: s.rec2,
      final: s.finalExam
    };
  });

  const prompt = `
    Como consultor pedagógico, analise os dados da turma "${classData.name}".
    Regras: Aprovado direto se soma dos 4 bimestres >= 28. Se < 28, vai para Prova Final.
    Média Final = (Soma + Prova Final) / 2. Aprovado se >= 5.

    Dados: ${JSON.stringify(analysisData)}

    Forneça:
    1. Resumo de aprovados/em risco.
    2. Alunos que precisam de atenção urgente (muito abaixo dos 28 pontos).
    3. Tendência de desempenho ao longo dos 4 bimestres.
    4. Sugestão de reforço para a Prova Final.

    Responda em Português (Brasil) formatado em Markdown.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Erro ao gerar análise.";
  } catch (error) {
    return "Erro de conexão com IA.";
  }
};

import React, { useState, useEffect } from 'react';
import { 
  Plus, GraduationCap, ChevronLeft, LayoutDashboard, Trash2, 
  UserPlus, Sparkles, AlertCircle, X, Users, Calculator, 
  ChevronRight, CheckCircle2, AlertTriangle, Info
} from 'lucide-react';
import { ClassRoom, Student, View, BimesterTab, GradePeriod } from './types';
import { Button } from './components/Button';
import { analyzeClassPerformance } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<View>('list');
  const [activeTab, setActiveTab] = useState<BimesterTab>(1);
  const [classes, setClasses] = useState<ClassRoom[]>([]);
  const [currentClass, setCurrentClass] = useState<ClassRoom | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isAddStudentModalOpen, setIsAddStudentModalOpen] = useState(false);
  const [bulkStudentNames, setBulkStudentNames] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('edugrade_v2_data');
    if (saved) setClasses(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('edugrade_v2_data', JSON.stringify(classes));
  }, [classes]);

  const handleCreateClass = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newClass: ClassRoom = {
      id: crypto.randomUUID(),
      name: formData.get('name') as string,
      subject: formData.get('subject') as string,
      year: formData.get('year') as string,
      activityCount: 3,
      students: []
    };
    setClasses([...classes, newClass]);
    setView('list');
