              <div><label className="block text-sm font-medium mb-1">Ano Letivo</label><input name="year" defaultValue="2026" className="w-full border rounded-lg px-3 py-2" /></div>
              <div className="pt-4 flex gap-2">
                <Button type="submit" className="flex-1">Criar</Button>
                <Button variant="secondary" type="button" onClick={() => setView('list')}>Cancelar</Button>
              </div>
            </form>
          </div>
        )}
        {view === 'detail' && renderDetail()}
      </main>

      {isAddStudentModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
