      // Lógica de substituição simplificada para visualização anual
      if (b === 1 && b1 < rec && b1 <= b2) return rec;
      if (b === 2 && b2 < rec && b2 < b1) return rec;
      return raw;
    }
    if (b === 3 || b === 4) {
      if (student.rec2 === null) return raw;
      const b3 = calcBimesterAvg(student.bimesters[3]);
      const b4 = calcBimesterAvg(student.bimesters[4]);
      const rec = student.rec2;

      if (b === 3 && b3 < rec && b3 <= b4) return rec;
      if (b === 4 && b4 < rec && b4 < b3) return rec;
      return raw;
    }
    return raw;
  };

  const renderClassList = () => (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-900">Diário de Classe</h1>
        <Button onClick={() => setView('create')}><Plus className="w-4 h-4 mr-2" /> Nova Turma</Button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {classes.map(cls => (
          <div key={cls.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-all cursor-pointer" onClick={() => { setCurrentClass(cls); setView('detail'); }}>
            <div className="flex justify-between items-start mb-2">
              <h3 className="font-bold text-lg">{cls.name}</h3>
              <button onClick={(e) => { e.stopPropagation(); if(confirm('Excluir?')) setClasses(classes.filter(c => c.id !== cls.id)); }} className="text-gray-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
            </div>
            <p className="text-indigo-600 font-medium text-sm">{cls.subject}</p>
            <div className="mt-4 flex items-center text-xs text-gray-500 gap-3">
              <span className="flex items-center"><Users className="w-3 h-3 mr-1" /> {cls.students.length} alunos</span>
              <span>{cls.year}</span>
            </div>
          </div>
        ))}
        {classes.length === 0 && (
          <div className="col-span-full py-12 text-center text-gray-400 border-2 border-dashed rounded-xl">
             <LayoutDashboard className="w-12 h-12 mx-auto mb-2 opacity-20" />
             <p>Nenhuma turma cadastrada.</p>
          </div>
        )}
      </div>
    </div>
  );

  const renderDetail = () => {
    if (!currentClass) return null;
    return (
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center">
            <Button variant="ghost" onClick={() => setView('list')}><ChevronLeft className="w-4 h-4" /></Button>
            <div className="ml-2">
              <h2 className="text-xl font-bold">{currentClass.name}</h2>
              <p className="text-sm text-gray-500">{currentClass.subject}</p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            {activeTab !== 'annual' && (
              <Button variant="secondary" onClick={handleAddActivityColumn} size="sm" className="bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100">
                <ListPlus className="w-4 h-4 mr-2" /> + Atividade
              </Button>
            )}
            <Button variant="secondary" onClick={() => setIsAddStudentModalOpen(true)} size="sm"><UserPlus className="w-4 h-4 mr-2" /> Alunos</Button>
            <Button onClick={async () => { setIsAnalyzing(true); setAiReport(await analyzeClassPerformance(currentClass)); setIsAnalyzing(false); }} size="sm" className="bg-purple-600 hover:bg-purple-700">
              <Sparkles className="w-4 h-4 mr-2" /> Analisar IA
            </Button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200 overflow-x-auto no-scrollbar bg-white rounded-t-xl px-2">
          {[1, 2, 3, 4, 'annual'].map(t => (
            <button
              key={t}
              onClick={() => { setActiveTab(t as BimesterTab); setAiReport(null); }}
              className={`px-6 py-4 text-sm font-bold whitespace-nowrap transition-colors border-b-2 ${activeTab === t ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
            >
              {t === 'annual' ? 'CONSOLIDADO ANUAL' : `${t}º BIMESTRE`}
            </button>
          ))}
        </div>

        {aiReport && (
          <div className="bg-purple-900 p-6 rounded-lg border border-purple-700 shadow-lg relative text-white animate-in fade-in slide-in-from-top-4 duration-300">
            <button onClick={() => setAiReport(null)} className="absolute top-4 right-4 text-purple-300 hover:text-white transition-colors"><X className="w-5 h-5" /></button>
            <div className="flex items-center gap-2 mb-4 text-purple-200 font-bold uppercase tracking-wider text-xs">
              <Sparkles className="w-4 h-4" /> Relatório de Inteligência Artificial
            </div>
            <div className="prose prose-invert prose-sm max-w-none whitespace-pre-wrap">{aiReport}</div>
          </div>
        )}

        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm border-collapse">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="px-6 py-4 font-bold text-gray-700 min-w-[220px] sticky left-0 bg-gray-50 z-10 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">Estudante</th>
                  {activeTab !== 'annual' ? (
                    <>
                      {Array.from({ length: currentClass.activityCount }).map((_, i) => (
                        <th key={i} className="px-2 py-4 text-center w-20 text-xs font-bold text-gray-500 uppercase">Ativ {i + 1}</th>
                      ))}
                      <th className="px-2 py-4 text-center w-24 bg-indigo-50 font-bold text-indigo-700 uppercase">Prova</th>
                      <th className="px-6 py-4 text-center w-32 font-bold text-indigo-900 bg-indigo-100/50 uppercase">Média Bim.</th>
                    </>
                  ) : (
                    <>
                      <th className="px-2 py-4 text-center font-bold text-gray-400">B1</th>
                      <th className="px-2 py-4 text-center font-bold text-gray-400">B2</th>
                      <th className="px-2 py-4 text-center bg-amber-50 text-amber-700 font-bold">REC 1</th>
                      <th className="px-2 py-4 text-center font-bold text-gray-400">B3</th>
                      <th className="px-2 py-4 text-center font-bold text-gray-400">B4</th>
                      <th className="px-2 py-4 text-center bg-amber-50 text-amber-700 font-bold">REC 2</th>
                      <th className="px-4 py-4 text-center font-bold bg-indigo-50 text-indigo-700">SOMA (28)</th>
                      <th className="px-2 py-4 text-center bg-rose-50 text-rose-700 font-bold">P. FINAL</th>
                      <th className="px-6 py-4 text-center font-bold text-indigo-900 bg-indigo-100 uppercase">Resultado</th>
                    </>
                  )}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {currentClass.students.map(student => {
                  if (activeTab === 'annual') {
                    const b1 = getEffectiveBimesterGrade(student, 1);
                    const b2 = getEffectiveBimesterGrade(student, 2);
                    const b3 = getEffectiveBimesterGrade(student, 3);
                    const b4 = getEffectiveBimesterGrade(student, 4);
                    const total = b1 + b2 + b3 + b4;
                    const needsFinal = total < 28;
                    const finalResult = needsFinal 
                      ? (total + (student.finalExam || 0)) / 2 
                      : total / 4;
                    const approved = needsFinal ? finalResult >= 5 : total >= 28;

                    return (
                      <tr key={student.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 font-semibold text-gray-900 sticky left-0 bg-white z-10 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{student.name}</td>
                        <td className="px-2 py-4 text-center text-gray-400 font-medium">{b1.toFixed(1)}</td>
                        <td className="px-2 py-4 text-center text-gray-400 font-medium">{b2.toFixed(1)}</td>
                        <td className="px-2 py-2 text-center bg-amber-50/30">
                          <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-slate-700 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-amber-500 outline-none transition-all" value={student.rec1 ?? ''} onChange={e => {
                            const val = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, rec1: val} : s)});
                          }} />
                        </td>
                        <td className="px-2 py-4 text-center text-gray-400 font-medium">{b3.toFixed(1)}</td>
                        <td className="px-2 py-4 text-center text-gray-400 font-medium">{b4.toFixed(1)}</td>
                        <td className="px-2 py-2 text-center bg-amber-50/30">
                          <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-slate-700 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-amber-500 outline-none transition-all" value={student.rec2 ?? ''} onChange={e => {
                            const val = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, rec2: val} : s)});
                          }} />
                        </td>
                        <td className={`px-4 py-4 text-center font-black text-base bg-indigo-50/30 ${total >= 28 ? 'text-green-600' : 'text-rose-600'}`}>{total.toFixed(1)}</td>
                        <td className="px-2 py-2 text-center bg-rose-50/30">
                          {needsFinal ? (
                            <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-slate-700 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-rose-500 outline-none transition-all" value={student.finalExam ?? ''} onChange={e => {
                              const val = e.target.value === '' ? null : parseFloat(e.target.value);
                              updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, finalExam: val} : s)});
                            }} />
                          ) : <span className="text-gray-300">-</span>}
                        </td>
                        <td className="px-6 py-4 text-center bg-indigo-100/20">
                          <span className={`px-3 py-1 rounded-full text-[11px] font-black uppercase tracking-widest ${approved ? 'bg-green-600 text-white' : 'bg-rose-600 text-white'}`}>
                            {approved ? 'Aprovado' : 'Reprovado'}
                          </span>
                        </td>
                      </tr>
                    );
                  }

                  const period = student.bimesters[activeTab as 1 | 2 | 3 | 4];
                  const avg = calcBimesterAvg(period);

                  return (
                    <tr key={student.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4 font-semibold text-gray-900 sticky left-0 bg-white z-10 shadow-[2px_0_5_rgba(0,0,0,0.02)]">{student.name}</td>
                      {period.activities.map((val, idx) => (
                        <td key={idx} className="px-1 py-2 text-center">
                          <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-slate-700 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-indigo-500 outline-none transition-all" value={val ?? ''} onChange={e => {
                            const newVal = e.target.value === '' ? null : parseFloat(e.target.value);
                            const updatedActs = [...period.activities];
                            updatedActs[idx] = newVal;
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, bimesters: {...s.bimesters, [activeTab]: {...period, activities: updatedActs}}} : s)});
                          }} />
                        </td>
                      ))}
                      <td className="px-1 py-2 text-center bg-indigo-50/50">
                         <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-indigo-300 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-indigo-600 outline-none transition-all shadow-sm" value={period.exam ?? ''} onChange={e => {
                            const newVal = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, bimesters: {...s.bimesters, [activeTab]: {...period, exam: newVal}}} : s)});
                          }} />
                      </td>
                      <td className="px-6 py-4 text-center font-black text-indigo-700 bg-indigo-100/30 text-base">{avg.toFixed(1)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans selection:bg-indigo-100 selection:text-indigo-900">
      <nav className="bg-white border-b sticky top-0 z-[100] px-6 h-16 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-2 cursor-pointer group" onClick={() => setView('list')}>
          <div className="bg-indigo-600 p-2 rounded-xl text-white group-hover:scale-110 transition-transform"><GraduationCap className="w-6 h-6" /></div>
          <span className="font-black text-2xl tracking-tighter">EduGrade <span className="text-xs font-bold text-slate-400 bg-slate-100 px-2 py-1 rounded ml-1">2.0 PRO</span></span>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-4 md:p-8">
        {view === 'list' && renderClassList()}
        {view === 'create' && (
          <div className="max-w-md mx-auto bg-white p-8 rounded-3xl shadow-xl border border-slate-100 animate-in zoom-in duration-300">
            <h2 className="text-2xl font-black mb-8 text-slate-800 tracking-tight">Novo Diário de Turma</h2>
            <form onSubmit={handleCreateClass} className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-slate-600 mb-2">Nome da Turma</label>
                <input name="name" required placeholder="Ex: 3º Ano Ensino Médio" className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl px-4 py-3 focus:ring-4 focus:ring-indigo-500/20 outline-none transition-all" />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-600 mb-2">Disciplina</label>
                <input name="subject" required placeholder="Ex: Matemática" className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl px-4 py-3 focus:ring-4 focus:ring-indigo-500/20 outline-none transition-all" />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-600 mb-2">Ano Letivo</label>
                <input name="year" defaultValue="2026" className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl px-4 py-3 focus:ring-4 focus:ring-indigo-500/20 outline-none transition-all" />
              </div>
              <div className="pt-4 flex gap-3">
                <Button type="submit" className="flex-1 py-4 text-base font-bold">Criar Diário</Button>
                <Button variant="ghost" type="button" onClick={() => setView('list')} className="px-6">Cancelar</Button>
              </div>
            </form>
          </div>
        )}
        {view === 'detail' && renderDetail()}
      </main>

      {isAddStudentModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in slide-in-from-bottom-8 duration-300">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50">
              <div>
                <h3 className="font-black text-2xl text-slate-800 tracking-tight">Importar Alunos</h3>
                <p className="text-slate-500 text-sm font-medium mt-1">Adicione vários alunos de uma vez.</p>
              </div>
              <button onClick={() => setIsAddStudentModalOpen(false)} className="bg-white p-2 rounded-full shadow-sm hover:bg-slate-100 transition-colors"><X className="w-6 h-6 text-slate-400" /></button>
            </div>
            <div className="p-8">
              <div className="bg-indigo-50 p-4 rounded-xl mb-6 flex gap-3 items-start">
                <Info className="w-5 h-5 text-indigo-600 mt-0.5 shrink-0" />
                <p className="text-xs text-indigo-800 leading-relaxed font-medium">
                  Copie a lista de nomes da sua planilha antiga, PDF ou WhatsApp e cole abaixo. 
                  Coloque um nome por linha para o sistema processar corretamente.
                </p>
              </div>
              <textarea 
                className="w-full h-80 bg-slate-900 text-white border border-slate-700 rounded-2xl p-6 text-base font-mono focus:ring-4 focus:ring-indigo-500/20 outline-none transition-all placeholder:text-slate-600"
                placeholder="Ex:&#10;Ana Maria Silva&#10;Bruno de Oliveira&#10;Carlos Eduardo..."
                value={bulkStudentNames}
                onChange={e => setBulkStudentNames(e.target.value)}
              />
            </div>
            <div className="p-8 bg-slate-50 border-t flex gap-4">
              <Button variant="secondary" className="flex-1 py-4 font-bold" onClick={() => setIsAddStudentModalOpen(false)}>Cancelar</Button>
              <Button className="flex-1 py-4 font-bold" onClick={handleAddStudents}>
                <Users className="w-5 h-5 mr-2" /> Adicionar {bulkStudentNames.split('\n').filter(n=>n.trim()).length} Alunos
              </Button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        input[type=number]::-webkit-inner-spin-button { -webkit-appearance: none; }
        input[type=number] { -moz-appearance: textfield; }

        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slide-in-top { from { transform: translateY(-10px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .animate-in { animation: fade-in 0.3s ease-out; }
        .slide-in-from-top-4 { animation: slide-in-top 0.4s cubic-bezier(0.16, 1, 0.3, 1); }
      `}</style>
    </div>
  );
};

export default App;

export interface GradePeriod {
  activities: (number | null)[];
  exam: number | null;
  extra: number | null; // Nota extra (ex: projetos)
}

export interface Student {
  id: string;
  name: string;
  bimesters: {
    1: GradePeriod;
    2: GradePeriod;
    3: GradePeriod;
    4: GradePeriod;
  };
  rec1: number | null; // Substitui menor nota de B1 ou B2
  rec2: number | null; // Substitui menor nota de B3 ou B4
  finalExam: number | null;
}

export interface ClassRoom {
  id: string;
  name: string;
  subject: string;
  year: string;
  activityCount: number; // Quantas colunas de atividade por bimestre
  students: Student[];
}

export type View = 'list' | 'detail' | 'create';
export type BimesterTab = 1 | 2 | 3 | 4 | 'annual';

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, GraduationCap, ChevronLeft, LayoutDashboard, Trash2, 
  UserPlus, Sparkles, AlertCircle, X, Users, Calculator, 
  ChevronRight, CheckCircle2, AlertTriangle, Info, ListPlus, Star
} from 'lucide-react';
import { ClassRoom, Student, View, BimesterTab, GradePeriod } from './types';
import { Button } from './components/Button';
import { analyzeClassPerformance } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<View>('list');
  const [activeTab, setActiveTab] = useState<BimesterTab>(1);
  const [classes, setClasses] = useState<ClassRoom[]>([]);
  const [currentClass, setCurrentClass] = useState<ClassRoom | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isAddStudentModalOpen, setIsAddStudentModalOpen] = useState(false);
  const [bulkStudentNames, setBulkStudentNames] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('edugrade_v2_data');
    if (saved) setClasses(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('edugrade_v2_data', JSON.stringify(classes));
  }, [classes]);

  const handleCreateClass = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newClass: ClassRoom = {
      id: crypto.randomUUID(),
      name: formData.get('name') as string,
      subject: formData.get('subject') as string,
      year: formData.get('year') as string,
      activityCount: 3,
      students: []
    };
    setClasses([...classes, newClass]);
    setView('list');
  };

  const updateClass = (updated: ClassRoom) => {
    setClasses(prev => prev.map(c => c.id === updated.id ? updated : c));
    setCurrentClass(updated);
  };

  const handleAddStudents = () => {
    if (!currentClass) return;
    const names = bulkStudentNames.split('\n').map(n => n.trim()).filter(n => n !== '');
    const newStudents: Student[] = names.map(name => ({
      id: crypto.randomUUID(),
      name,
      bimesters: {
        1: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
        2: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
        3: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
        4: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
      },
      rec1: null, rec2: null, finalExam: null
    }));
    updateClass({ ...currentClass, students: [...currentClass.students, ...newStudents] });
    setBulkStudentNames('');
    setIsAddStudentModalOpen(false);
  };

  const handleAddActivityColumn = () => {
    if (!currentClass) return;
    const newCount = currentClass.activityCount + 1;
    const updatedStudents = currentClass.students.map(student => ({
      ...student,
      bimesters: {
        1: { ...student.bimesters[1], activities: [...student.bimesters[1].activities, null] },
        2: { ...student.bimesters[2], activities: [...student.bimesters[2].activities, null] },
        3: { ...student.bimesters[3], activities: [...student.bimesters[3].activities, null] },
        4: { ...student.bimesters[4], activities: [...student.bimesters[4].activities, null] },
      }
    }));
    updateClass({ ...currentClass, activityCount: newCount, students: updatedStudents });
  };

  const calcBimesterAvg = (period: GradePeriod) => {
    const validActs = period.activities.filter(v => v !== null) as number[];
    const avgActs = validActs.length > 0 ? validActs.reduce((a, b) => a + b, 0) / validActs.length : 0;
    const exam = period.exam || 0;
    const extra = period.extra || 0;
    // Fórmula: ((Média das atividades + Nota da prova)/2)+Extra
    return ((avgActs + exam) / 2) + extra;
  };

  const getEffectiveBimesterGrade = (student: Student, b: 1 | 2 | 3 | 4) => {
    const raw = calcBimesterAvg(student.bimesters[b]);
    if (b === 1 || b === 2) {
      if (student.rec1 === null) return raw;
      const b1 = calcBimesterAvg(student.bimesters[1]);
      const b2 = calcBimesterAvg(student.bimesters[2]);
      const rec = student.rec1;

      if (b === 1 && b1 < rec && b1 <= b2) return rec;
      if (b === 2 && b2 < rec && b2 < b1) return rec;
      return raw;
    }
    if (b === 3 || b === 4) {
      if (student.rec2 === null) return raw;
      const b3 = calcBimesterAvg(student.bimesters[3]);
      const b4 = calcBimesterAvg(student.bimesters[4]);
      const rec = student.rec2;

      if (b === 3 && b3 < rec && b3 <= b4) return rec;
      if (b === 4 && b4 < rec && b4 < b3) return rec;
      return raw;
    }
    return raw;
  };

  const renderClassList = () => (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-900">Diário de Classe</h1>
        <Button onClick={() => setView('create')}><Plus className="w-4 h-4 mr-2" /> Nova Turma</Button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {classes.map(cls => (
          <div key={cls.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-all cursor-pointer" onClick={() => { setCurrentClass(cls); setView('detail'); }}>
            <div className="flex justify-between items-start mb-2">
              <h3 className="font-bold text-lg">{cls.name}</h3>
              <button onClick={(e) => { e.stopPropagation(); if(confirm('Excluir?')) setClasses(classes.filter(c => c.id !== cls.id)); }} className="text-gray-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
            </div>
            <p className="text-indigo-600 font-medium text-sm">{cls.subject}</p>
            <div className="mt-4 flex items-center text-xs text-gray-500 gap-3">
              <span className="flex items-center"><Users className="w-3 h-3 mr-1" /> {cls.students.length} alunos</span>
              <span>{cls.year}</span>
            </div>
          </div>
        ))}
        {classes.length === 0 && (
          <div className="col-span-full py-12 text-center text-gray-400 border-2 border-dashed rounded-xl">
             <LayoutDashboard className="w-12 h-12 mx-auto mb-2 opacity-20" />
             <p>Nenhuma turma cadastrada.</p>
          </div>
        )}
      </div>
    </div>
  );

  const renderDetail = () => {
    if (!currentClass) return null;
    return (
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center">
            <Button variant="ghost" onClick={() => setView('list')}><ChevronLeft className="w-4 h-4" /></Button>
            <div className="ml-2">
              <h2 className="text-xl font-bold">{currentClass.name}</h2>
              <p className="text-sm text-gray-500">{currentClass.subject}</p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            {activeTab !== 'annual' && (
              <Button variant="secondary" onClick={handleAddActivityColumn} size="sm" className="bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100">
                <ListPlus className="w-4 h-4 mr-2" /> + Atividade
              </Button>
            )}
            <Button variant="secondary" onClick={() => setIsAddStudentModalOpen(true)} size="sm"><UserPlus className="w-4 h-4 mr-2" /> Alunos</Button>
            <Button onClick={async () => { setIsAnalyzing(true); setAiReport(await analyzeClassPerformance(currentClass)); setIsAnalyzing(false); }} size="sm" className="bg-purple-600 hover:bg-purple-700">
              <Sparkles className="w-4 h-4 mr-2" /> Analisar IA
            </Button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200 overflow-x-auto no-scrollbar bg-white rounded-t-xl px-2">
          {[1, 2, 3, 4, 'annual'].map(t => (
            <button
              key={t}
              onClick={() => { setActiveTab(t as BimesterTab); setAiReport(null); }}
              className={`px-6 py-4 text-sm font-bold whitespace-nowrap transition-colors border-b-2 ${activeTab === t ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
            >
              {t === 'annual' ? 'CONSOLIDADO ANUAL' : `${t}º BIMESTRE`}
            </button>
          ))}
        </div>

        {aiReport && (
          <div className="bg-purple-900 p-6 rounded-lg border border-purple-700 shadow-lg relative text-white animate-in fade-in slide-in-from-top-4 duration-300">
            <button onClick={() => setAiReport(null)} className="absolute top-4 right-4 text-purple-300 hover:text-white transition-colors"><X className="w-5 h-5" /></button>
            <div className="flex items-center gap-2 mb-4 text-purple-200 font-bold uppercase tracking-wider text-xs">
              <Sparkles className="w-4 h-4" /> Relatório de Inteligência Artificial
            </div>
            <div className="prose prose-invert prose-sm max-w-none whitespace-pre-wrap">{aiReport}</div>
          </div>
        )}

        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm border-collapse">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="px-6 py-4 font-bold text-gray-700 min-w-[220px] sticky left-0 bg-gray-50 z-10 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">Estudante</th>
                  {activeTab !== 'annual' ? (
                    <>
                      {Array.from({ length: currentClass.activityCount }).map((_, i) => (
                        <th key={i} className="px-2 py-4 text-center w-20 text-xs font-bold text-gray-500 uppercase">Ativ {i + 1}</th>
                      ))}
                      <th className="px-2 py-4 text-center w-24 bg-indigo-50 font-bold text-indigo-700 uppercase">Prova</th>
                      <th className="px-2 py-4 text-center w-20 bg-amber-50 font-bold text-amber-700 uppercase">
                        <div className="flex flex-col items-center">
                          <Star className="w-3 h-3 mb-0.5" />
                          <span>Extra</span>
                        </div>
                      </th>
                      <th className="px-6 py-4 text-center w-32 font-bold text-indigo-900 bg-indigo-100/50 uppercase">Média Bim.</th>
                    </>
                  ) : (
                    <>
                      <th className="px-2 py-4 text-center font-bold text-gray-400">B1</th>
                      <th className="px-2 py-4 text-center font-bold text-gray-400">B2</th>
                      <th className="px-2 py-4 text-center bg-amber-50 text-amber-700 font-bold">REC 1</th>
                      <th className="px-2 py-4 text-center font-bold text-gray-400">B3</th>
                      <th className="px-2 py-4 text-center font-bold text-gray-400">B4</th>
                      <th className="px-2 py-4 text-center bg-amber-50 text-amber-700 font-bold">REC 2</th>
                      <th className="px-4 py-4 text-center font-bold bg-indigo-50 text-indigo-700">SOMA (28)</th>
                      <th className="px-2 py-4 text-center bg-rose-50 text-rose-700 font-bold">P. FINAL</th>
                      <th className="px-6 py-4 text-center font-bold text-indigo-900 bg-indigo-100 uppercase">Resultado</th>
                    </>
                  )}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {currentClass.students.map(student => {
                  if (activeTab === 'annual') {
                    const b1 = getEffectiveBimesterGrade(student, 1);
                    const b2 = getEffectiveBimesterGrade(student, 2);
                    const b3 = getEffectiveBimesterGrade(student, 3);
                    const b4 = getEffectiveBimesterGrade(student, 4);
                    const total = b1 + b2 + b3 + b4;
                    const needsFinal = total < 28;
                    const finalResult = needsFinal 
                      ? (total + (student.finalExam || 0)) / 2 
                      : total / 4;
                    const approved = needsFinal ? finalResult >= 5 : total >= 28;

                    return (
                      <tr key={student.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 font-semibold text-gray-900 sticky left-0 bg-white z-10 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{student.name}</td>
                        <td className="px-2 py-4 text-center text-gray-400 font-medium">{b1.toFixed(1)}</td>
                        <td className="px-2 py-4 text-center text-gray-400 font-medium">{b2.toFixed(1)}</td>
                        <td className="px-2 py-2 text-center bg-amber-50/30">
                          <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-slate-700 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-amber-500 outline-none transition-all" value={student.rec1 ?? ''} onChange={e => {
                            const val = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, rec1: val} : s)});
                          }} />
                        </td>
                        <td className="px-2 py-4 text-center text-gray-400 font-medium">{b3.toFixed(1)}</td>
                        <td className="px-2 py-4 text-center text-gray-400 font-medium">{b4.toFixed(1)}</td>
                        <td className="px-2 py-2 text-center bg-amber-50/30">
                          <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-slate-700 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-amber-500 outline-none transition-all" value={student.rec2 ?? ''} onChange={e => {
                            const val = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, rec2: val} : s)});
                          }} />
                        </td>
                        <td className={`px-4 py-4 text-center font-black text-base bg-indigo-50/30 ${total >= 28 ? 'text-green-600' : 'text-rose-600'}`}>{total.toFixed(1)}</td>
                        <td className="px-2 py-2 text-center bg-rose-50/30">
                          {needsFinal ? (
                            <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-slate-700 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-rose-500 outline-none transition-all" value={student.finalExam ?? ''} onChange={e => {
                              const val = e.target.value === '' ? null : parseFloat(e.target.value);
                              updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, finalExam: val} : s)});
                            }} />
                          ) : <span className="text-gray-300">-</span>}
                        </td>
                        <td className="px-6 py-4 text-center bg-indigo-100/20">
                          <span className={`px-3 py-1 rounded-full text-[11px] font-black uppercase tracking-widest ${approved ? 'bg-green-600 text-white' : 'bg-rose-600 text-white'}`}>
                            {approved ? 'Aprovado' : 'Reprovado'}
                          </span>
                        </td>
                      </tr>
                    );
                  }

                  const bimesterKey = activeTab as 1 | 2 | 3 | 4;
                  const period = student.bimesters[bimesterKey];
                  const avg = calcBimesterAvg(period);

                  return (
                    <tr key={student.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4 font-semibold text-gray-900 sticky left-0 bg-white z-10 shadow-[2px_0_5_rgba(0,0,0,0.02)]">{student.name}</td>
                      {period.activities.map((val, idx) => (
                        <td key={idx} className="px-1 py-2 text-center">
                          <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-slate-700 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-indigo-500 outline-none transition-all" value={val ?? ''} onChange={e => {
                            const newVal = e.target.value === '' ? null : parseFloat(e.target.value);
                            const updatedActs = [...period.activities];
                            updatedActs[idx] = newVal;
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, bimesters: {...s.bimesters, [bimesterKey]: {...period, activities: updatedActs}}} : s)});
                          }} />
                        </td>
                      ))}
                      <td className="px-1 py-2 text-center bg-indigo-50/50">
                         <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-indigo-300 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-indigo-600 outline-none transition-all shadow-sm" value={period.exam ?? ''} onChange={e => {
                            const newVal = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, bimesters: {...s.bimesters, [bimesterKey]: {...period, exam: newVal}}} : s)});
                          }} />
                      </td>
                      <td className="px-1 py-2 text-center bg-amber-50/50">
                         <input type="number" step="0.1" className="w-14 text-center bg-slate-900 text-white border border-amber-300 rounded-md py-1.5 font-bold focus:ring-2 focus:ring-amber-600 outline-none transition-all shadow-sm" value={period.extra ?? ''} onChange={e => {
                            const newVal = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, bimesters: {...s.bimesters, [bimesterKey]: {...period, extra: newVal}}} : s)});
                          }} />
                      </td>
                      <td className="px-6 py-4 text-center font-black text-indigo-700 bg-indigo-100/30 text-base">{avg.toFixed(1)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans selection:bg-indigo-100 selection:text-indigo-900">
      <nav className="bg-white border-b sticky top-0 z-[100] px-6 h-16 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-2 cursor-pointer group" onClick={() => setView('list')}>
          <div className="bg-indigo-600 p-2 rounded-xl text-white group-hover:scale-110 transition-transform"><GraduationCap className="w-6 h-6" /></div>
          <span className="font-black text-2xl tracking-tighter">EduGrade <span className="text-xs font-bold text-slate-400 bg-slate-100 px-2 py-1 rounded ml-1">2.0 PRO</span></span>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-4 md:p-8">
        {view === 'list' && renderClassList()}
        {view === 'create' && (
          <div className="max-w-md mx-auto bg-white p-8 rounded-3xl shadow-xl border border-slate-100 animate-in zoom-in duration-300">
            <h2 className="text-2xl font-black mb-8 text-slate-800 tracking-tight">Novo Diário de Turma</h2>
            <form onSubmit={handleCreateClass} className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-slate-600 mb-2">Nome da Turma</label>
                <input name="name" required placeholder="Ex: 3º Ano Ensino Médio" className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl px-4 py-3 focus:ring-4 focus:ring-indigo-500/20 outline-none transition-all" />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-600 mb-2">Disciplina</label>
                <input name="subject" required placeholder="Ex: Matemática" className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl px-4 py-3 focus:ring-4 focus:ring-indigo-500/20 outline-none transition-all" />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-600 mb-2">Ano Letivo</label>
                <input name="year" defaultValue="2026" className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl px-4 py-3 focus:ring-4 focus:ring-indigo-500/20 outline-none transition-all" />
              </div>
              <div className="pt-4 flex gap-3">
                <Button type="submit" className="flex-1 py-4 text-base font-bold">Criar Diário</Button>
                <Button variant="ghost" type="button" onClick={() => setView('list')} className="px-6">Cancelar</Button>
              </div>
            </form>
          </div>
        )}
        {view === 'detail' && renderDetail()}
      </main>

      {isAddStudentModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in slide-in-from-bottom-8 duration-300">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50">
              <div>
                <h3 className="font-black text-2xl text-slate-800 tracking-tight">Importar Alunos</h3>
                <p className="text-slate-500 text-sm font-medium mt-1">Adicione vários alunos de uma vez.</p>
              </div>
              <button onClick={() => setIsAddStudentModalOpen(false)} className="bg-white p-2 rounded-full shadow-sm hover:bg-slate-100 transition-colors"><X className="w-6 h-6 text-slate-400" /></button>
            </div>
            <div className="p-8">
              <div className="bg-indigo-50 p-4 rounded-xl mb-6 flex gap-3 items-start">
                <Info className="w-5 h-5 text-indigo-600 mt-0.5 shrink-0" />
                <p className="text-xs text-indigo-800 leading-relaxed font-medium">
                  Copie a lista de nomes da sua planilha antiga, PDF ou WhatsApp e cole abaixo. 
                  Coloque um nome por linha para o sistema processar corretamente.
                </p>
              </div>
              <textarea 
                className="w-full h-80 bg-slate-900 text-white border border-slate-700 rounded-2xl p-6 text-base font-mono focus:ring-4 focus:ring-indigo-500/20 outline-none transition-all placeholder:text-slate-600"
                placeholder="Ex:&#10;Ana Maria Silva&#10;Bruno de Oliveira&#10;Carlos Eduardo..."
                value={bulkStudentNames}
                onChange={e => setBulkStudentNames(e.target.value)}
              />
            </div>
            <div className="p-8 bg-slate-50 border-t flex gap-4">
              <Button variant="secondary" className="flex-1 py-4 font-bold" onClick={() => setIsAddStudentModalOpen(false)}>Cancelar</Button>
              <Button className="flex-1 py-4 font-bold" onClick={handleAddStudents}>
                <Users className="w-5 h-5 mr-2" /> Adicionar {bulkStudentNames.split('\n').filter(n=>n.trim()).length} Alunos
              </Button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        input[type=number]::-webkit-inner-spin-button { -webkit-appearance: none; }
        input[type=number] { -moz-appearance: textfield; }

        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slide-in-top { from { transform: translateY(-10px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .animate-in { animation: fade-in 0.3s ease-out; }
        .slide-in-from-top-4 { animation: slide-in-top 0.4s cubic-bezier(0.16, 1, 0.3, 1); }
      `}</style>
    </div>
  );
};

export default App;

export interface GradePeriod {
  activities: (number | null)[];
  exam: number | null;
  extra: number | null; // Nota extra para projetos
}

export interface Student {
  id: string;
  name: string;
  bimesters: {
    1: GradePeriod;
    2: GradePeriod;
    3: GradePeriod;
    4: GradePeriod;
  };
  rec1: number | null; // Substitui menor nota de B1 ou B2
  rec2: number | null; // Substitui menor nota de B3 ou B4
  finalExam: number | null;
}

export interface ClassRoom {
  id: string;
  name: string;
  subject: string;
  year: string;
  activityCount: number; // Quantas colunas de atividade por bimestre
  students: Student[];
}

export type View = 'list' | 'detail' | 'create';
export type BimesterTab = 1 | 2 | 3 | 4 | 'annual';

import React, { useState, useEffect } from 'react';
import { 
  Plus, GraduationCap, ChevronLeft, LayoutDashboard, Trash2, 
  UserPlus, Sparkles, X, Users, ListPlus, Star, Info
} from 'lucide-react';
import { ClassRoom, Student, View, BimesterTab, GradePeriod } from './types';
import { Button } from './components/Button';
import { analyzeClassPerformance } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<View>('list');
  const [activeTab, setActiveTab] = useState<BimesterTab>(1);
  const [classes, setClasses] = useState<ClassRoom[]>([]);
  const [currentClass, setCurrentClass] = useState<ClassRoom | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isAddStudentModalOpen, setIsAddStudentModalOpen] = useState(false);
  const [bulkStudentNames, setBulkStudentNames] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('edugrade_v2_data');
    if (saved) setClasses(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('edugrade_v2_data', JSON.stringify(classes));
  }, [classes]);

  const handleCreateClass = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newClass: ClassRoom = {
      id: crypto.randomUUID(),
      name: formData.get('name') as string,
      subject: formData.get('subject') as string,
      year: formData.get('year') as string,
      activityCount: 3,
      students: []
    };
    setClasses([...classes, newClass]);
    setView('list');
  };

  const updateClass = (updated: ClassRoom) => {
    setClasses(prev => prev.map(c => c.id === updated.id ? updated : c));
    setCurrentClass(updated);
  };

  const handleAddStudents = () => {
    if (!currentClass) return;
    const names = bulkStudentNames.split('\n').map(n => n.trim()).filter(n => n !== '');
    const newStudents: Student[] = names.map(name => ({
      id: crypto.randomUUID(),
      name,
      bimesters: {
        1: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
        2: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
        3: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
        4: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
      },
      rec1: null, rec2: null, finalExam: null
    }));
    updateClass({ ...currentClass, students: [...currentClass.students, ...newStudents] });
    setBulkStudentNames('');
    setIsAddStudentModalOpen(false);
  };

  const handleAddActivityColumn = () => {
    if (!currentClass) return;
    const newCount = currentClass.activityCount + 1;
    const updatedStudents = currentClass.students.map(student => ({
      ...student,
      bimesters: {
        1: { ...student.bimesters[1], activities: [...student.bimesters[1].activities, null] },
        2: { ...student.bimesters[2], activities: [...student.bimesters[2].activities, null] },
        3: { ...student.bimesters[3], activities: [...student.bimesters[3].activities, null] },
        4: { ...student.bimesters[4], activities: [...student.bimesters[4].activities, null] },
      }
    }));
    updateClass({ ...currentClass, activityCount: newCount, students: updatedStudents });
  };

  // Cálculo da nota do bimestre: ((Média das atividades + Nota da prova)/2) + Extra
  const calcBimesterAvg = (period: GradePeriod) => {
    const validActs = period.activities.filter(v => v !== null) as number[];
    const avgActs = validActs.length > 0 ? validActs.reduce((a, b) => a + b, 0) / validActs.length : 0;
    const exam = period.exam || 0;
    const extra = period.extra || 0;
    return ((avgActs + exam) / 2) + extra;
  };

  // Lógica de Recuperação Paralela (Substitui a menor nota entre B1/B2 ou B3/B4)
  const getEffectiveBimesterGrade = (student: Student, b: 1 | 2 | 3 | 4) => {
    const raw = calcBimesterAvg(student.bimesters[b]);
    if (b === 1 || b === 2) {
      if (student.rec1 === null) return raw;
      const b1 = calcBimesterAvg(student.bimesters[1]);
      const b2 = calcBimesterAvg(student.bimesters[2]);
      const rec = student.rec1;
      if (b === 1 && b1 < rec && b1 <= b2) return rec;
      if (b === 2 && b2 < rec && b2 < b1) return rec;
      return raw;
    }
    if (b === 3 || b === 4) {
      if (student.rec2 === null) return raw;
      const b3 = calcBimesterAvg(student.bimesters[3]);
      const b4 = calcBimesterAvg(student.bimesters[4]);
      const rec = student.rec2;
      if (b === 3 && b3 < rec && b3 <= b4) return rec;
      if (b === 4 && b4 < rec && b4 < b3) return rec;
      return raw;
    }
    return raw;
  };

  const renderClassList = () => (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-900 tracking-tight">Diários de Classe</h1>
        <Button onClick={() => setView('create')}><Plus className="w-4 h-4 mr-2" /> Nova Turma</Button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {classes.map(cls => (
          <div key={cls.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:shadow-lg transition-all cursor-pointer group" onClick={() => { setCurrentClass(cls); setView('detail'); }}>
            <div className="flex justify-between items-start mb-3">
              <h3 className="font-bold text-xl text-slate-800">{cls.name}</h3>
              <button onClick={(e) => { e.stopPropagation(); if(confirm('Excluir esta turma permanentemente?')) setClasses(classes.filter(c => c.id !== cls.id)); }} className="text-slate-300 hover:text-rose-500 transition-colors p-1"><Trash2 className="w-5 h-5" /></button>
            </div>
            <p className="text-indigo-600 font-bold text-sm bg-indigo-50 px-3 py-1 rounded-full inline-block mb-6 tracking-wide uppercase">{cls.subject}</p>
            <div className="flex items-center text-xs font-semibold text-slate-500 gap-4">
              <span className="flex items-center"><Users className="w-4 h-4 mr-1.5 opacity-50" /> {cls.students.length} alunos</span>
              <span className="bg-slate-100 px-2 py-0.5 rounded uppercase">{cls.year}</span>
            </div>
          </div>
        ))}
        {classes.length === 0 && (
          <div className="col-span-full py-20 text-center text-slate-400 border-4 border-dashed rounded-3xl border-slate-200">
             <LayoutDashboard className="w-16 h-16 mx-auto mb-4 opacity-10" />
             <p className="text-lg font-medium">Você ainda não tem turmas cadastradas.</p>
             <Button variant="ghost" onClick={() => setView('create')} className="mt-4">Clique para começar</Button>
          </div>
        )}
      </div>
    </div>
  );

  const renderDetail = () => {
    if (!currentClass) return null;
    return (
      <div className="space-y-6 animate-in slide-in-from-top-2 duration-300">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div className="flex items-center">
            <Button variant="ghost" onClick={() => setView('list')} className="mr-4 hover:bg-slate-200"><ChevronLeft className="w-5 h-5" /></Button>
            <div>
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">{currentClass.name}</h2>
              <p className="text-sm font-bold text-indigo-600 uppercase tracking-widest">{currentClass.subject}</p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            {activeTab !== 'annual' && (
              <Button variant="secondary" onClick={handleAddActivityColumn} size="sm" className="bg-emerald-600 text-white hover:bg-emerald-700 border-none">
                <ListPlus className="w-4 h-4 mr-2" /> + Atividade
              </Button>
            )}
            <Button variant="secondary" onClick={() => setIsAddStudentModalOpen(true)} size="sm" className="font-bold border-slate-300"><UserPlus className="w-4 h-4 mr-2" /> Importar Alunos</Button>
            <Button onClick={async () => { setIsAnalyzing(true); setAiReport(await analyzeClassPerformance(currentClass)); setIsAnalyzing(false); }} size="sm" className="bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 border-none text-white shadow-md">
              <Sparkles className="w-4 h-4 mr-2" /> {isAnalyzing ? 'Analisando...' : 'IA Mentor'}
            </Button>
          </div>
        </div>

        <div className="flex border-b border-slate-200 overflow-x-auto no-scrollbar bg-white rounded-t-3xl px-4 pt-4">
          {[1, 2, 3, 4, 'annual'].map(t => (
            <button
              key={t}
              onClick={() => { setActiveTab(t as BimesterTab); setAiReport(null); }}
              className={`px-8 py-4 text-sm font-black whitespace-nowrap transition-all border-b-4 ${activeTab === t ? 'border-indigo-600 text-indigo-600 translate-y-px' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
            >
              {t === 'annual' ? 'CONSOLIDADO ANUAL' : `${t}º BIMESTRE`}
            </button>
          ))}
        </div>

        {aiReport && (
          <div className="bg-slate-900 p-8 rounded-3xl border border-indigo-500/30 shadow-2xl relative text-white animate-in zoom-in duration-300">
            <button onClick={() => setAiReport(null)} className="absolute top-6 right-6 text-slate-400 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
            <div className="flex items-center gap-3 mb-6 text-indigo-400 font-black uppercase tracking-[0.2em] text-xs">
              <Sparkles className="w-5 h-5" /> Relatório Estratégico IA
            </div>
            <div className="prose prose-invert prose-indigo max-w-none text-slate-300 leading-relaxed whitespace-pre-wrap font-medium">{aiReport}</div>
          </div>
        )}

        <div className="bg-white rounded-b-3xl border border-slate-200 shadow-xl overflow-hidden mb-20">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm border-collapse">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-8 py-5 font-black text-slate-700 min-w-[260px] sticky left-0 bg-slate-50 z-20 shadow-[4px_0_10px_rgba(0,0,0,0.03)] uppercase tracking-wider">Estudante</th>
                  {activeTab !== 'annual' ? (
                    <>
                      {Array.from({ length: currentClass.activityCount }).map((_, i) => (
                        <th key={i} className="px-3 py-5 text-center w-20 text-[10px] font-black text-slate-400 uppercase tracking-widest">Ativ {i + 1}</th>
                      ))}
                      <th className="px-3 py-5 text-center w-28 bg-indigo-50 font-black text-indigo-700 uppercase tracking-widest">Prova</th>
                      <th className="px-3 py-5 text-center w-24 bg-amber-50 font-black text-amber-700 uppercase tracking-widest">
                        <div className="flex flex-col items-center">
                          <Star className="w-4 h-4 mb-1" />
                          <span>Extra</span>
                        </div>
                      </th>
                      <th className="px-8 py-5 text-center w-40 font-black text-indigo-900 bg-indigo-100 uppercase tracking-widest">Média Bim.</th>
                    </>
                  ) : (
                    <>
                      <th className="px-3 py-5 text-center font-bold text-slate-400 uppercase tracking-tighter">B1</th>
                      <th className="px-3 py-5 text-center font-bold text-slate-400 uppercase tracking-tighter">B2</th>
                      <th className="px-3 py-5 text-center bg-amber-50 text-amber-700 font-black uppercase tracking-tighter">REC 1</th>
                      <th className="px-3 py-5 text-center font-bold text-slate-400 uppercase tracking-tighter">B3</th>
                      <th className="px-3 py-5 text-center font-bold text-slate-400 uppercase tracking-tighter">B4</th>
                      <th className="px-3 py-5 text-center bg-amber-50 text-amber-700 font-black uppercase tracking-tighter">REC 2</th>
                      <th className="px-6 py-5 text-center font-black bg-indigo-50 text-indigo-700 uppercase tracking-tighter">Soma</th>
                      <th className="px-3 py-5 text-center bg-rose-50 text-rose-700 font-black uppercase tracking-tighter">P. Final</th>
                      <th className="px-8 py-5 text-center font-black text-white bg-slate-900 uppercase tracking-widest">Resultado</th>
                    </>
                  )}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {currentClass.students.map(student => {
                  if (activeTab === 'annual') {
                    const b1 = getEffectiveBimesterGrade(student, 1);
                    const b2 = getEffectiveBimesterGrade(student, 2);
                    const b3 = getEffectiveBimesterGrade(student, 3);
                    const b4 = getEffectiveBimesterGrade(student, 4);
                    const totalSoma = b1 + b2 + b3 + b4;
                    const mediaAnual = totalSoma / 4;
                    const needsFinal = mediaAnual < 7; // Aprovação direta média 7 (ou soma 28)

                    // Nova Fórmula: (Média Anual + Prova Final) / 2 >= 5
                    const mediaFinal = needsFinal 
                      ? (mediaAnual + (student.finalExam || 0)) / 2 
                      : mediaAnual;
                    const approved = mediaFinal >= 5;

                    return (
                      <tr key={student.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-8 py-5 font-bold text-slate-800 sticky left-0 bg-white z-20 shadow-[4px_0_10px_rgba(0,0,0,0.02)]">{student.name}</td>
                        <td className="px-3 py-5 text-center text-slate-400 font-bold">{b1.toFixed(1)}</td>
                        <td className="px-3 py-5 text-center text-slate-400 font-bold">{b2.toFixed(1)}</td>
                        <td className="px-3 py-3 text-center bg-amber-50/30">
                          <input type="number" step="0.1" className="w-16 text-center bg-slate-900 text-white border border-slate-700 rounded-xl py-2 font-black focus:ring-4 focus:ring-amber-500/20 outline-none" value={student.rec1 ?? ''} onChange={e => {
                            const val = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, rec1: val} : s)});
                          }} />
                        </td>
                        <td className="px-3 py-5 text-center text-slate-400 font-bold">{b3.toFixed(1)}</td>
                        <td className="px-3 py-5 text-center text-slate-400 font-bold">{b4.toFixed(1)}</td>
                        <td className="px-3 py-3 text-center bg-amber-50/30">
                          <input type="number" step="0.1" className="w-16 text-center bg-slate-900 text-white border border-slate-700 rounded-xl py-2 font-black focus:ring-4 focus:ring-amber-500/20 outline-none" value={student.rec2 ?? ''} onChange={e => {
                            const val = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, rec2: val} : s)});
                          }} />
                        </td>
                        <td className={`px-6 py-5 text-center font-black text-lg bg-indigo-50/30 ${totalSoma >= 28 ? 'text-green-600' : 'text-rose-600'}`}>{totalSoma.toFixed(1)}</td>
                        <td className="px-3 py-3 text-center bg-rose-50/30">
                          {needsFinal ? (
                            <input type="number" step="0.1" className="w-16 text-center bg-slate-900 text-white border border-slate-700 rounded-xl py-2 font-black focus:ring-4 focus:ring-rose-500/20 outline-none transition-all" value={student.finalExam ?? ''} onChange={e => {
                              const val = e.target.value === '' ? null : parseFloat(e.target.value);
                              updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, finalExam: val} : s)});
                            }} />
                          ) : <span className="text-slate-300 font-black">OK</span>}
                        </td>
                        <td className="px-8 py-5 text-center bg-slate-900/5">
                          <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-[0.15em] shadow-sm ${approved ? 'bg-emerald-500 text-white' : 'bg-rose-600 text-white'}`}>
                            {approved ? 'Aprovado' : 'Reprovado'}
                          </span>
                        </td>
                      </tr>
                    );
                  }

                  const bimesterKey = activeTab as 1 | 2 | 3 | 4;
                  const period = student.bimesters[bimesterKey];
                  const avg = calcBimesterAvg(period);

                  return (
                    <tr key={student.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-8 py-5 font-bold text-slate-800 sticky left-0 bg-white z-20 shadow-[4px_0_10px_rgba(0,0,0,0.02)]">{student.name}</td>
                      {period.activities.map((val, idx) => (
                        <td key={idx} className="px-1.5 py-3 text-center">
                          <input type="number" step="0.1" className="w-16 text-center bg-slate-900 text-white border border-slate-700 rounded-xl py-2 font-black focus:ring-4 focus:ring-indigo-500/20 outline-none" value={val ?? ''} onChange={e => {
                            const newVal = e.target.value === '' ? null : parseFloat(e.target.value);
                            const updatedActs = [...period.activities];
                            updatedActs[idx] = newVal;
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, bimesters: {...s.bimesters, [bimesterKey]: {...period, activities: updatedActs}}} : s)});
                          }} />
                        </td>
                      ))}
                      <td className="px-1.5 py-3 text-center bg-indigo-50/50">
                         <input type="number" step="0.1" className="w-16 text-center bg-slate-900 text-white border border-indigo-500/40 rounded-xl py-2 font-black focus:ring-4 focus:ring-indigo-600/20 outline-none" value={period.exam ?? ''} onChange={e => {
                            const newVal = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, bimesters: {...s.bimesters, [bimesterKey]: {...period, exam: newVal}}} : s)});
                          }} />
                      </td>
                      <td className="px-1.5 py-3 text-center bg-amber-50/50">
                         <input type="number" step="0.1" className="w-16 text-center bg-slate-900 text-white border border-amber-400/40 rounded-xl py-2 font-black focus:ring-4 focus:ring-amber-500/20 outline-none" value={period.extra ?? ''} onChange={e => {
                            const newVal = e.target.value === '' ? null : parseFloat(e.target.value);
                            updateClass({...currentClass, students: currentClass.students.map(s => s.id === student.id ? {...s, bimesters: {...s.bimesters, [bimesterKey]: {...period, extra: newVal}}} : s)});
                          }} />
                      </td>
                      <td className="px-8 py-5 text-center font-black text-indigo-700 bg-indigo-100/40 text-lg">{avg.toFixed(1)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {currentClass.students.length === 0 && (
            <div className="py-20 text-center text-slate-400">
               <UserPlus className="w-12 h-12 mx-auto mb-2 opacity-20" />
               <p className="font-bold">Ainda não há alunos nesta turma.</p>
               <Button variant="ghost" size="sm" onClick={() => setIsAddStudentModalOpen(true)} className="mt-2 text-indigo-600">Importar lista agora</Button>
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans selection:bg-indigo-600 selection:text-white pb-20">
      <nav className="bg-white border-b border-slate-200 sticky top-0 z-[100] px-8 h-20 flex items-center justify-between shadow-sm backdrop-blur-md bg-white/90">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('list')}>
          <div className="bg-slate-900 p-2.5 rounded-2xl text-white group-hover:rotate-6 transition-all shadow-lg shadow-slate-900/20"><GraduationCap className="w-7 h-7" /></div>
          <div>
            <span className="font-black text-2xl tracking-tighter block leading-none">EduGrade</span>
            <span className="text-[10px] font-black text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full tracking-widest uppercase">Professor Pro</span>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-4 md:p-10">
        {view === 'list' && renderClassList()}
        {view === 'create' && (
          <div className="max-w-xl mx-auto bg-white p-10 rounded-[3rem] shadow-2xl border border-slate-100 animate-in zoom-in slide-in-from-bottom-10 duration-500">
            <h2 className="text-3xl font-black mb-10 text-slate-900 tracking-tight text-center">Configurar Novo Diário</h2>
            <form onSubmit={handleCreateClass} className="space-y-8">
              <div>
                <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Nome da Turma</label>
                <input name="name" required placeholder="Ex: 3º Ano Ensino Médio" className="w-full bg-slate-50 text-slate-900 border-2 border-slate-100 rounded-3xl px-6 py-4 font-bold focus:bg-white focus:border-indigo-600 outline-none transition-all" />
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Disciplina</label>
                  <input name="subject" required placeholder="Matemática" className="w-full bg-slate-50 text-slate-900 border-2 border-slate-100 rounded-3xl px-6 py-4 font-bold focus:bg-white focus:border-indigo-600 outline-none transition-all" />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Ano Letivo</label>
                  <input name="year" defaultValue="2026" className="w-full bg-slate-50 text-slate-900 border-2 border-slate-100 rounded-3xl px-6 py-4 font-bold focus:bg-white focus:border-indigo-600 outline-none transition-all" />
                </div>
              </div>
              <div className="pt-6 flex gap-4">
                <Button type="submit" className="flex-1 py-5 text-lg font-black bg-slate-900 hover:bg-slate-800 rounded-3xl shadow-xl shadow-slate-900/10">Salvar Turma</Button>
                <Button variant="ghost" type="button" onClick={() => setView('list')} className="px-8 font-bold">Voltar</Button>
              </div>
            </form>
          </div>
        )}
        {view === 'detail' && renderDetail()}
      </main>

      {isAddStudentModalOpen && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[200] flex items-center justify-center p-6 overflow-y-auto">
          <div className="bg-white w-full max-w-3xl rounded-[3rem] shadow-2xl overflow-hidden animate-in zoom-in slide-in-from-bottom-20 duration-500">
            <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h3 className="font-black text-3xl text-slate-900 tracking-tight">Carga de Alunos</h3>
                <p className="text-slate-500 text-sm font-bold mt-1 tracking-wide uppercase">Importação Inteligente em Lote</p>
              </div>
              <button onClick={() => setIsAddStudentModalOpen(false)} className="bg-white p-3 rounded-2xl shadow-sm hover:scale-110 active:scale-95 transition-all text-slate-400 hover:text-rose-500"><X className="w-7 h-7" /></button>
            </div>
            <div className="p-10">
              <div className="bg-indigo-50 p-6 rounded-3xl mb-8 flex gap-4 items-center border border-indigo-100">
                <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-lg shadow-indigo-600/30"><Info className="w-6 h-6" /></div>
                <p className="text-sm text-indigo-900 leading-snug font-bold">
                  Cole os nomes diretamente do Excel ou WhatsApp. <br/>
                  <span className="opacity-60 text-xs">O sistema criará os registros automaticamente para cada linha colada.</span>
                </p>
              </div>
              <textarea 
                className="w-full h-80 bg-slate-900 text-white border border-slate-700 rounded-[2rem] p-8 text-lg font-mono focus:ring-8 focus:ring-indigo-500/10 outline-none transition-all placeholder:text-slate-700"
                placeholder="Exemplo:&#10;Alice Moreira&#10;Bernardo Souza..."
                value={bulkStudentNames}
                onChange={e => setBulkStudentNames(e.target.value)}
              />
            </div>
            <div className="p-10 bg-slate-50 border-t border-slate-100 flex gap-6">
              <Button variant="ghost" className="flex-1 py-5 font-black text-slate-400" onClick={() => setIsAddStudentModalOpen(false)}>Descartar</Button>
              <Button className="flex-1 py-5 font-black bg-indigo-600 rounded-3xl shadow-xl shadow-indigo-600/20" onClick={handleAddStudents}>
                <Plus className="w-5 h-5 mr-3" /> Gerar {bulkStudentNames.split('\n').filter(n=>n.trim()).length} Alunos
              </Button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        input[type=number]::-webkit-inner-spin-button { -webkit-appearance: none; }
        input[type=number] { -moz-appearance: textfield; }

        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slide-in-top { from { transform: translateY(-10px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .animate-in { animation: fade-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Plus, GraduationCap, ChevronLeft, LayoutDashboard, Trash2, 
  UserPlus, Sparkles, X, Users, ListPlus, Star, Info
} from 'lucide-react';
import { ClassRoom, Student, View, BimesterTab, GradePeriod } from './types';
import { Button } from './components/Button';
import { analyzeClassPerformance } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<View>('list');
  const [activeTab, setActiveTab] = useState<BimesterTab>(1);
  const [classes, setClasses] = useState<ClassRoom[]>([]);
  const [currentClass, setCurrentClass] = useState<ClassRoom | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isAddStudentModalOpen, setIsAddStudentModalOpen] = useState(false);
  const [bulkStudentNames, setBulkStudentNames] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('edugrade_v2_data');
    if (saved) setClasses(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('edugrade_v2_data', JSON.stringify(classes));
  }, [classes]);

  const handleCreateClass = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newClass: ClassRoom = {
      id: crypto.randomUUID(),
      name: formData.get('name') as string,
      subject: formData.get('subject') as string,
      year: formData.get('year') as string,
      activityCount: 3,
      students: []
    };
    setClasses([...classes, newClass]);
    setView('list');
  };

  const updateClass = (updated: ClassRoom) => {
    setClasses(prev => prev.map(c => c.id === updated.id ? updated : c));
    setCurrentClass(updated);
  };

  const handleAddStudents = () => {
    if (!currentClass) return;
    const names = bulkStudentNames.split('\n').map(n => n.trim()).filter(n => n !== '');
    const newStudents: Student[] = names.map(name => ({
      id: crypto.randomUUID(),
      name,
      bimesters: {
        1: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
        2: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
        3: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
        4: { activities: Array(currentClass.activityCount).fill(null), exam: null, extra: null },
      },
      rec1: null, rec2: null, finalExam: null
    }));
    updateClass({ ...currentClass, students: [...currentClass.students, ...newStudents] });
    setBulkStudentNames('');
    setIsAddStudentModalOpen(false);
  };

  const handleAddActivityColumn = () => {
    if (!currentClass) return;
    const newCount = currentClass.activityCount + 1;
    const updatedStudents = currentClass.students.map(student => ({
      ...student,
      bimesters: {
        1: { ...student.bimesters[1], activities: [...student.bimesters[1].activities, null] },
        2: { ...student.bimesters[2], activities: [...student.bimesters[2].activities, null] },
        3: { ...student.bimesters[3], activities: [...student.bimesters[3].activities, null] },
        4: { ...student.bimesters[4], activities: [...student.bimesters[4].activities, null] },
      }
    }));
    updateClass({ ...currentClass, activityCount: newCount, students: updatedStudents });
  };

  // Cálculo da nota do bimestre: ((Média das atividades + Nota da prova)/2) + Extra
  const calcBimesterAvg = (period: GradePeriod) => {
    const validActs = period.activities.filter(v => v !== null) as number[];
    const avgActs = validActs.length > 0 ? validActs.reduce((a, b) => a + b, 0) / validActs.length : 0;
    const exam = period.exam || 0;
    const extra = period.extra || 0;
    return ((avgActs + exam) / 2) + extra;
  };

  // Lógica de Recuperação Paralela (Substitui a menor nota entre B1/B2 ou B3/B4)
  const getEffectiveBimesterGrade = (student: Student, b: 1 | 2 | 3 | 4) => {
    const raw = calcBimesterAvg(student.bimesters[b]);
    if (b === 1 || b === 2) {
      if (student.rec1 === null) return raw;
      const b1 = calcBimesterAvg(student.bimesters[1]);
      const b2 = calcBimesterAvg(student.bimesters[2]);
      const rec = student.rec1;
      if (b === 1 && b1 < rec && b1 <= b2) return rec;
      if (b === 2 && b2 < rec && b2 < b1) return rec;
      return raw;
    }
    if (b === 3 || b === 4) {
      if (student.rec2 === null) return raw;
      const b3 = calcBimesterAvg(student.bimesters[3]);
      const b4 = calcBimesterAvg(student.bimesters[4]);
      const rec = student.rec2;
      if (b === 3 && b3 < rec && b3 <= b4) return rec;
      if (b === 4 && b4 < rec && b4 < b3) return rec;
      return raw;
    }
    return raw;
  };

  const renderClassList = () => (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-900 tracking-tight">Diários de Classe</h1>
        <Button onClick={() => setView('create')}><Plus className="w-4 h-4 mr-2" /> Nova Turma</Button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {classes.map(cls => (
          <div key={cls.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:shadow-lg transition-all cursor-pointer group" onClick={() => { setCurrentClass(cls); setView('detail'); }}>
            <div className="flex justify-between items-start mb-3">
              <h3 className="font-bold text-xl text-slate-800">{cls.name}</h3>
              <button onClick={(e) => { e.stopPropagation(); if(confirm('Excluir esta turma permanentemente?')) setClasses(classes.filter(c => c.id !== cls.id)); }} className="text-slate-300 hover:text-rose-500 transition-colors p-1"><Trash2 className="w-5 h-5" /></button>
            </div>
            <p className="text-indigo-600 font-bold text-sm bg-indigo-50 px-3 py-1 rounded-full inline-block mb-6 tracking-wide uppercase">{cls.subject}</p>
            <div className="flex items-center text-xs font-semibold text-slate-500 gap-4">
              <span className="flex items-center"><Users className="w-4 h-4 mr-1.5 opacity-50" /> {cls.students.length} alunos</span>
              <span className="bg-slate-100 px-2 py-0.5 rounded uppercase">{cls.year}</span>
            </div>
          </div>
        ))}
        {classes.length === 0 && (
          <div className="col-span-full py-20 text-center text-slate-400 border-4 border-dashed rounded-3xl border-slate-200">
             <LayoutDashboard className="w-16 h-16 mx-auto mb-4 opacity-10" />
             <p className="text-lg font-medium">Você ainda não tem turmas cadastradas.</p>
             <Button variant="ghost" onClick={() => setView('create')} className="mt-4">Clique para começar</Button>
          </div>
        )}
      </div>
    </div>
  );

  const renderDetail = () => {
    if (!currentClass) return null;
    return (
      <div className="space-y-6 animate-in slide-in-from-top-2 duration-300">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div className="flex items-center">
            <Button variant="ghost" onClick={() => setView('list')} className="mr-4 hover:bg-slate-200"><ChevronLeft className="w-5 h-5" /></Button>
            <div>
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">{currentClass.name}</h2>
              <p className="text-sm font-bold text-indigo-600 uppercase tracking-widest">{currentClass.subject}</p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            {activeTab !== 'annual' && (
              <Button variant="secondary" onClick={handleAddActivityColumn} size="sm" className="bg-emerald-600 text-white hover:bg-emerald-700 border-none">
                <ListPlus className="w-4 h-4 mr-2" /> + Atividade
              </Button>
            )}
            <Button variant="secondary" onClick={() => setIsAddStudentModalOpen(true)} size="sm" className="font-bold border-slate-300"><UserPlus className="w-4 h-4 mr-2" /> Importar Alunos</Button>
            <Button onClick={async () => { setIsAnalyzing(true); setAiReport(await analyzeClassPerformance(currentClass)); setIsAnalyzing(false); }} size="sm" className="bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 border-none text-white shadow-md">
              <Sparkles className="w-4 h-4 mr-2" /> {isAnalyzing ? 'Analisando...' : 'IA Mentor'}
            </Button>
          </div>
        </div>

        <div className="flex border-b border-slate-200 overflow-x-auto no-scrollbar bg-white rounded-t-3xl px-4 pt-4">
          {[1, 2, 3, 4, 'annual'].map(t => (
            <button
              key={t}
              onClick={() => { setActiveTab(t as BimesterTab); setAiReport(null); }}
              className={`px-8 py-4 text-sm font-black whitespace-nowrap transition-all border-b-4 ${activeTab === t ? 'border-indigo-600 text-indigo-600 translate-y-px' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
            >
              {t === 'annual' ? 'CONSOLIDADO ANUAL' : `${t}º BIMESTRE`}
            </button>
          ))}
        </div>

        {aiReport && (
          <div className="bg-slate-900 p-8 rounded-3xl border border-indigo-500/30 shadow-2xl relative text-white animate-in zoom-in duration-300">
            <button onClick={() => setAiReport(null)} className="absolute top-6 right-6 text-slate-400 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
            <div className="flex items-center gap-3 mb-6 text-indigo-400 font-black uppercase tracking-[0.2em] text-xs">
              <Sparkles className="w-5 h-5" /> Relatório Estratégico IA
            </div>
            <div className="prose prose-invert prose-indigo max-w-none text-slate-300 leading-relaxed whitespace-pre-wrap font-medium">{aiReport}</div>
          </div>
        )}

        <div className="bg-white rounded-b-3xl border border-slate-200 shadow-xl overflow-hidden mb-20">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm border-collapse">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-8 py-5 font-black text-slate-700 min-w-[260px] sticky left-0 bg-slate-50 z-20 shadow-[4px_0_10px_rgba(0,0,0,0.03)] uppercase tracking-wider">Estudante</th>
                  {activeTab !== 'annual' ? (
                    <>
                      {Array.from({ length: currentClass.activityCount }).map((_, i) => (
                        <th key={i} className="px-3 py-5 text-center w-20 text-[10px] font-black text-slate-400 uppercase tracking-widest">Ativ {i + 1}</th>
                      ))}
                      <th className="px-3 py-5 text-center w-28 bg-indigo-50 font-black text-indigo-700 uppercase tracking-widest">Prova</th>
                      <th className="px-3 py-5 text-center w-24 bg-amber-50 font-black text-amber-700 uppercase tracking-widest">
                        <div className="flex flex-col items-center">
