              <input 
                name="password"
                type="password" 
                required 
                placeholder="Sua senha secreta" 
                className="w-full bg-slate-50 text-slate-900 border-2 border-slate-50 rounded-[2rem] pl-16 pr-6 py-5 font-bold focus:bg-white focus:border-indigo-600 outline-none transition-all placeholder:text-slate-400"
              />
