                  className="w-full bg-slate-50 text-slate-900 border-2 border-slate-50 rounded-[2rem] pl-16 pr-6 py-5 font-bold focus:bg-white focus:border-indigo-600 outline-none transition-all placeholder:text-slate-400"
                />
              </div>
            )}
          </div>

          <button 
            type="submit" 
            className="w-full bg-slate-900 text-white rounded-[2.5rem] py-6 font-black text-lg shadow-2xl shadow-slate-900/20 hover:bg-slate-800 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center group"
          >
            {authMode === 'login' ? 'Entrar no Sistema' : 'Finalizar Cadastro'}
            <ArrowRight className="w-6 h-6 ml-3 group-hover:translate-x-2 transition-transform" />
          </button>

          <div className="text-center pt-4">
            <button 
              type="button"
              onClick={() => { setAuthMode(authMode === 'login' ? 'register' : 'login'); setAuthError(null); }}
              className="text-sm font-black text-indigo-600 hover:text-indigo-800 transition-colors bg-indigo-50 px-6 py-2 rounded-full"
            >
              {authMode === 'login' ? 'Não tem conta? Cadastre-se' : 'Já tem conta? Faça Login'}
            </button>
          </div>
        </form>
      </div>
