import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  define: {
    // Garante que o código em geminiService.ts encontre a chave de ambiente
    'process.env.API_KEY': JSON.stringify(process.env.API_KEY)
