  const handleRestoreClass = (id: string) => {
    const updated = classes.map(c => c.id === id ? { ...c, status: 'active' as const, lastModified: Date.now() } : c);
    notifyDataChange(updated);
  };

  const updateClass = (updated: ClassRoom) => {
