    sourcemap: false
  }
});

import { createClient } from '@supabase/supabase-js';

// Tenta obter de múltiplas fontes para garantir compatibilidade com Vercel e Vite
const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || (process as any).env?.VITE_SUPABASE_URL || '';
const supabaseAnonKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || (process as any).env?.VITE_SUPABASE_ANON_KEY || '';

// Se as chaves estiverem vazias, o app não deve quebrar o script inteiro, mas o Supabase não funcionará.
// O createClient exige strings não vazias.
