                  <button onClick={() => { if(confirm('Excluir?')) notifyDataChange(classes.filter(c => c.id !== cls.id)); }} className="text-rose-400 hover:bg-rose-50 p-2 rounded-xl"><Trash2 className="w-5 h-5" /></button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
